from functools import cache


def most_points(values: list[int]) -> int:
    @cache
    def best(row):                       # try each item next; every subset of the row is a state
        top = 0
        for p in range(len(row)):
            left = row[p - 1] if p > 0 else 1
            right = row[p + 1] if p + 1 < len(row) else 1
            top = max(top, left * row[p] * right + best(row[:p] + row[p + 1:]))
        return top
    return best(tuple(values))
